mod cli;
mod http_client;
mod stats;
mod output;

use anyhow::Result;
use std::time::Duration;

#[tokio::main]
async fn main() -> Result<()> {
    let args = cli::Args::parse();

    if args.debug {
        // Debug mode: single request and dump
        http_client::debug_request(&args).await?;
        return Ok(());
    }

    // Run the load test
    let results = http_client::run_load_test(&args).await?;

    // Output the results
    output::write_results(&args, &results)?;

    Ok(())
}
