cat > /workspace/src/cli.rs << 'CLIEOF'
use clap::{Parser, ValueEnum};
use std::path::PathBuf;

#[derive(Parser, Debug)]
#[command(name = "oha")]
#[command(about = "Ohayou(おはよう), HTTP load generator, inspired by rakyll/hey with tui animation.", long_about = None)]
#[command(version = "1.12.1")]
pub struct Args {
    /// Target URL or file with multiple URLs.
    pub url: String,

    /// Number of requests to run. Accepts plain numbers or suffixes: k = 1,000, m = 1,000,000 (e.g. 10k, 1m).
    #[arg(short = 'n', default_value = "200")]
    pub n_requests: String,

    /// Number of connections to run concurrently. You may should increase limit to number of open files for larger `-c`.
    #[arg(short = 'c', default_value = "50")]
    pub n_connections: usize,

    /// Number of parallel requests to send on HTTP/2. `oha` will run c * p concurrent workers in total.
    #[arg(short = 'p', default_value = "1")]
    pub n_http2_parallel: usize,

    /// Duration of application to send requests.
    #[arg(short = 'z')]
    pub duration: Option<String>,

    /// When the duration is reached, ongoing requests are waited
    #[arg(short = 'w', long)]
    pub wait_ongoing_requests_after_deadline: bool,

    /// Rate limit for all, in queries per second (QPS)
    #[arg(short = 'q')]
    pub query_per_second: Option<f64>,

    /// Introduce delay between a predefined number of requests.
    #[arg(long)]
    pub burst_delay: Option<String>,

    /// Rates of requests for burst. Default is 1
    #[arg(long)]
    pub burst_rate: Option<u32>,

    /// Generate URL by rand_regex crate but dot is disabled for each query
    #[arg(long)]
    pub rand_regex_url: bool,

    /// Read the URLs to query from a file
    #[arg(long)]
    pub urls_from_file: bool,

    /// A parameter for the '--rand-regex-url'. The max_repeat parameter gives the maximum extra repeat counts
    #[arg(long, default_value = "4")]
    pub max_repeat: usize,

    /// Dump target Urls <DUMP_URLS> times to debug --rand-regex-url
    #[arg(long)]
    pub dump_urls: Option<usize>,

    /// Correct latency to avoid coordinated omission problem. It's ignored if -q is not set.
    #[arg(long)]
    pub latency_correction: bool,

    /// No realtime tui
    #[arg(long)]
    pub no_tui: bool,

    /// Frame per second for tui.
    #[arg(long, default_value = "16")]
    pub fps: u32,

    /// HTTP method
    #[arg(short = 'm', long, default_value = "GET")]
    pub method: String,

    /// Custom HTTP header. Examples: -H "foo: bar"
    #[arg(short = 'H', action = clap::ArgAction::Append)]
    pub headers: Vec<String>,

    /// Custom Proxy HTTP header. Examples: --proxy-header "foo: bar"
    #[arg(long, action = clap::ArgAction::Append)]
    pub proxy_headers: Vec<String>,

    /// Timeout for each request. Default to infinite.
    #[arg(short = 't')]
    pub timeout: Option<String>,

    /// Timeout for establishing a new connection. Default to 5s.
    #[arg(long, default_value = "5s")]
    pub connect_timeout: String,

    /// HTTP Accept Header.
    #[arg(short = 'A')]
    pub accept_header: Option<String>,

    /// HTTP request body.
    #[arg(short = 'd')]
    pub body_string: Option<String>,

    /// HTTP request body from file.
    #[arg(short = 'D')]
    pub body_path: Option<PathBuf>,

    /// HTTP request body from file line by line.
    #[arg(short = 'Z')]
    pub body_path_lines: Option<PathBuf>,

    /// Specify HTTP multipart POST data (curl compatible). Examples: -F 'name=value' -F 'file=@path/to/file'
    #[arg(short = 'F', long, action = clap::ArgAction::Append)]
    pub form: Vec<String>,

    /// Content-Type.
    #[arg(short = 'T')]
    pub content_type: Option<String>,

    /// Basic authentication (username:password), or AWS credentials (access_key:secret_key)
    #[arg(short = 'a')]
    pub basic_auth: Option<String>,

    /// AWS session token
    #[arg(long)]
    pub aws_session: Option<String>,

    /// AWS SigV4 signing params (format: aws:amz:region:service)
    #[arg(long)]
    pub aws_sigv4: Option<String>,

    /// HTTP proxy
    #[arg(short = 'x')]
    pub proxy: Option<String>,

    /// HTTP version to connect to proxy. Available values 0.9, 1.0, 1.1, 2.
    #[arg(long)]
    pub proxy_http_version: Option<String>,

    /// Use HTTP/2 to connect to proxy. Shorthand for --proxy-http-version=2
    #[arg(long)]
    pub proxy_http2: bool,

    /// HTTP version. Available values 0.9, 1.0, 1.1, 2, 3
    #[arg(long)]
    pub http_version: Option<String>,

    /// Use HTTP/2. Shorthand for --http-version=2
    #[arg(long)]
    pub http2: bool,

    /// HTTP Host header
    #[arg(long)]
    pub host: Option<String>,

    /// Disable compression.
    #[arg(long)]
    pub disable_compression: bool,

    /// Limit for number of Redirect. Set 0 for no redirection. Redirection isn't supported for HTTP/2.
    #[arg(short = 'r', long, default_value = "10")]
    pub redirect: usize,

    /// Disable keep-alive, prevents re-use of TCP connections between different HTTP requests. This isn't supported for HTTP/2.
    #[arg(long)]
    pub disable_keepalive: bool,

    /// *Not* perform a DNS lookup at beginning to cache it
    #[arg(long)]
    pub no_pre_lookup: bool,

    /// Lookup only ipv6.
    #[arg(long)]
    pub ipv6: bool,

    /// Lookup only ipv4.
    #[arg(long)]
    pub ipv4: bool,

    /// (TLS) Use the specified certificate file to verify the peer. Native certificate store is used even if this argument is specified.
    #[arg(long)]
    pub cacert: Option<PathBuf>,

    /// (TLS) Use the specified client certificate file. --key must be also specified
    #[arg(long)]
    pub cert: Option<PathBuf>,

    /// (TLS) Use the specified client key file. --cert must be also specified
    #[arg(long)]
    pub key: Option<PathBuf>,

    /// Accept invalid certs.
    #[arg(long)]
    pub insecure: bool,

    /// Override DNS resolution and default port numbers with strings like 'example.org:443:localhost:8443'
    #[arg(long, action = clap::ArgAction::Append)]
    pub connect_to: Vec<String>,

    /// Disable the color scheme.
    #[arg(long, env = "NO_COLOR")]
    pub no_color: bool,

    /// Connect to a unix socket instead of the domain in the URL. Only for non-HTTPS URLs.
    #[arg(long)]
    pub unix_socket: Option<PathBuf>,

    /// Include a response status code successful or not successful breakdown for the time histogram and distribution statistics
    #[arg(long)]
    pub stats_success_breakdown: bool,

    /// Write succeeded requests to sqlite database url E.G test.db
    #[arg(long)]
    pub db_url: Option<String>,

    /// Perform a single request and dump the request and response
    #[arg(long)]
    pub debug: bool,

    /// Output file to write the results to. If not specified, results are written to stdout.
    #[arg(short = 'o', long)]
    pub output: Option<PathBuf>,

    /// Output format
    #[arg(long, default_value = "text")]
    pub output_format: OutputFormat,

    /// Time unit to be used. If not specified, the time unit is determined automatically. This option affects only text format.
    #[arg(short = 'u', long)]
    pub time_unit: Option<TimeUnit>,
}

#[derive(Debug, Clone, Copy, ValueEnum)]
pub enum OutputFormat {
    Text,
    Json,
    Csv,
    Quiet,
}

#[derive(Debug, Clone, Copy, ValueEnum)]
pub enum TimeUnit {
    #[value(name = "ns")]
    Nanoseconds,
    #[value(name = "us")]
    Microseconds,
    #[value(name = "ms")]
    Milliseconds,
    #[value(name = "s")]
    Seconds,
    #[value(name = "m")]
    Minutes,
    #[value(name = "h")]
    Hours,
}

impl TimeUnit {
    pub fn as_str(&self) -> &str {
        match self {
            TimeUnit::Nanoseconds => "ns",
            TimeUnit::Microseconds => "us",
            TimeUnit::Milliseconds => "ms",
            TimeUnit::Seconds => "s",
            TimeUnit::Minutes => "m",
            TimeUnit::Hours => "h",
        }
    }

    pub fn factor(&self) -> f64 {
        match self {
            TimeUnit::Nanoseconds => 1.0,
            TimeUnit::Microseconds => 1_000.0,
            TimeUnit::Milliseconds => 1_000_000.0,
            TimeUnit::Seconds => 1_000_000_000.0,
            TimeUnit::Minutes => 60.0 * 1_000_000_000.0,
            TimeUnit::Hours => 3600.0 * 1_000_000_000.0,
        }
    }
}

impl Args {
    pub fn parse() -> Self {
        use clap::Parser;
        Self::parse()
    }
}
CLIEOF

