use std::collections::BTreeMap;
use std::time::Duration;

#[derive(Debug, Clone)]
pub struct RequestResult {
    pub status: u16,
    pub duration: Duration,
    pub dns_duration: Duration,
    pub dialup_duration: Duration,
    pub response_delay: Duration,
    pub bytes: usize,
    pub error: Option<String>,
}

#[derive(Debug, Clone)]
pub struct Statistics {
    pub results: Vec<RequestResult>,
    pub start_time: std::time::Instant,
    pub end_time: std::time::Instant,
}

impl Statistics {
    pub fn new() -> Self {
        let now = std::time::Instant::now();
        Statistics {
            results: Vec::new(),
            start_time: now,
            end_time: now,
        }
    }

    pub fn add_result(&mut self, result: RequestResult) {
        self.results.push(result);
        self.end_time = std::time::Instant::now();
    }

    pub fn success_count(&self) -> usize {
        self.results.iter().filter(|r| r.error.is_none()).count()
    }

    pub fn error_count(&self) -> usize {
        self.results.iter().filter(|r| r.error.is_some()).count()
    }

    pub fn success_rate(&self) -> f64 {
        if self.results.is_empty() {
            return 0.0;
        }
        self.success_count() as f64 / self.results.len() as f64
    }

    pub fn total_duration(&self) -> Duration {
        self.end_time.duration_since(self.start_time)
    }

    pub fn total_bytes(&self) -> usize {
        self.results.iter().map(|r| r.bytes).sum()
    }

    pub fn get_percentile(&self, percentile: f64) -> Option<Duration> {
        if self.results.is_empty() {
            return None;
        }

        let mut durations: Vec<Duration> = self.results
            .iter()
            .filter(|r| r.error.is_none())
            .map(|r| r.duration)
            .collect();

        if durations.is_empty() {
            return None;
        }

        durations.sort();

        let index = ((percentile / 100.0) * durations.len() as f64).ceil() as usize;
        let index = std::cmp::min(index, durations.len() - 1);

        Some(durations[index])
    }

    pub fn min_duration(&self) -> Option<Duration> {
        self.results
            .iter()
            .filter(|r| r.error.is_none())
            .map(|r| r.duration)
            .min()
    }

    pub fn max_duration(&self) -> Option<Duration> {
        self.results
            .iter()
            .filter(|r| r.error.is_none())
            .map(|r| r.duration)
            .max()
    }

    pub fn avg_duration(&self) -> Option<Duration> {
        let successful: Vec<_> = self.results
            .iter()
            .filter(|r| r.error.is_none())
            .collect();

        if successful.is_empty() {
            return None;
        }

        let sum: Duration = successful.iter().map(|r| r.duration).sum();
        Some(sum / successful.len() as u32)
    }

    pub fn requests_per_sec(&self) -> f64 {
        let total = self.total_duration().as_secs_f64();
        if total == 0.0 {
            return 0.0;
        }
        self.success_count() as f64 / total
    }

    pub fn size_per_sec(&self) -> f64 {
        let total = self.total_duration().as_secs_f64();
        if total == 0.0 {
            return 0.0;
        }
        self.total_bytes() as f64 / total
    }

    pub fn avg_size(&self) -> usize {
        if self.results.is_empty() {
            return 0;
        }
        self.total_bytes() / self.results.len()
    }

    pub fn histogram_buckets(&self, bucket_count: usize) -> BTreeMap<u64, u32> {
        if self.results.is_empty() {
            return BTreeMap::new();
        }

        let successful: Vec<_> = self.results
            .iter()
            .filter(|r| r.error.is_none())
            .collect();

        if successful.is_empty() {
            return BTreeMap::new();
        }

        let min_nanos = successful
            .iter()
            .map(|r| r.duration.as_nanos() as u64)
            .min()
            .unwrap_or(0);
        let max_nanos = successful
            .iter()
            .map(|r| r.duration.as_nanos() as u64)
            .max()
            .unwrap_or(0);

        if min_nanos == max_nanos {
            let mut map = BTreeMap::new();
            map.insert(min_nanos, successful.len() as u32);
            return map;
        }

        let range = max_nanos - min_nanos;
        let step = (range / bucket_count as u64).max(1);

        let mut map = BTreeMap::new();
        for result in successful {
            let nanos = result.duration.as_nanos() as u64;
            let bucket = if nanos <= min_nanos {
                min_nanos
            } else {
                min_nanos + ((nanos - min_nanos) / step) * step
            };
            *map.entry(bucket).or_insert(0) += 1;
        }

        map
    }

    pub fn status_code_distribution(&self) -> BTreeMap<u16, u32> {
        let mut map = BTreeMap::new();
        for result in &self.results {
            if result.error.is_none() {
                *map.entry(result.status).or_insert(0) += 1;
            }
        }
        map
    }
}
