pub async fn run_load_test(args: &Args) -> Result<Statistics> {
    let total_requests = parse_number(&args.n_requests)?;
    let duration = parse_duration(args.duration.as_deref());

    let client = build_client(args)?;

    let mut stats = Statistics::new();

    // Simple implementation: send requests sequentially for now
    for i in 0..total_requests {
        let start = Instant::now();

        let result = make_request(&client, args).await;

        let duration = start.elapsed();

        match result {
            Ok((status, bytes, dns_duration, dialup_duration, response_delay)) => {
                stats.add_result(RequestResult {
                    status,
                    duration,
                    dns_duration,
                    dialup_duration,
                    response_delay,
                    bytes,
                    error: None,
                });
            }
            Err(e) => {
                stats.add_result(RequestResult {
                    status: 0,
                    duration,
                    dns_duration: Duration::ZERO,
                    dialup_duration: Duration::ZERO,
                    response_delay: Duration::ZERO,
                    bytes: 0,
                    error: Some(e.to_string()),
                });
            }
        }

        if let Some(dur) = duration {
            if start.elapsed() > dur {
                break;
            }
        }
    }

    Ok(stats)
}

async fn make_request(
    client: &Client,
    args: &Args,
) -> Result<(u16, usize, Duration, Duration, Duration)> {
    let start = Instant::now();

    let body = build_body(args)?;
    let mut request_builder = match args.method.as_str() {
        "GET" => client.get(&args.url),
        "POST" => client.post(&args.url),
        "PUT" => client.put(&args.url),
        "DELETE" => client.delete(&args.url),
        "PATCH" => client.patch(&args.url),
        "HEAD" => client.head(&args.url),
        "OPTIONS" => client.request(reqwest::Method::OPTIONS, &args.url),
        _ => client.request(reqwest::Method::from_bytes(args.method.as_bytes())?, &args.url),
    };

    // Add headers
    for header in &args.headers {
        if let Some((key, val)) = header.split_once(':') {
            request_builder = request_builder.header(key.trim(), val.trim());
        }
    }

    if let Some(accept) = &args.accept_header {
        request_builder = request_builder.header("Accept", accept);
    }

    if let Some(host) = &args.host {
        request_builder = request_builder.header("Host", host);
    }

    request_builder = request_builder.header("User-Agent", "oha/1.12.1");

    if let Some(body) = body {
        request_builder = request_builder.body(body);
    }

    if let Some(timeout_str) = &args.timeout {
        let timeout_dur = humantime::parse_duration(timeout_str)?;
        request_builder = request_builder.timeout(timeout_dur);
    }

    let response = request_builder.send().await?;
    let dialup_time = start.elapsed();

    let status = response.status().as_u16();
    let body_bytes = response.bytes().await?;
    let bytes = body_bytes.len();

    // Estimate times (these are rough estimates since reqwest doesn't expose them directly)
    let dns_duration = Duration::from_micros(50); // Rough estimate
    let response_delay = Duration::from_micros(100); // Rough estimate

    Ok((status, bytes, dns_duration, dialup_duration, response_delay))
}

fn build_client(args: &Args) -> Result<Client> {
    let mut builder = Client::builder();

    if args.disable_compression {
        builder = builder.no_gzip().no_deflate().no_brotli();
    }

    if args.disable_keepalive {
        builder = builder.http1_title_case_headers();
    }

    if args.redirect == 0 {
        builder = builder.redirect(reqwest::redirect::Policy::none());
    } else {
        builder = builder.redirect(reqwest::redirect::Policy::limited(args.redirect));
    }

    if args.insecure {
        builder = builder.danger_accept_invalid_certs(true);
    }

    if args.http2 {
        builder = builder.http2_prior_knowledge();
    }

    if let Some(timeout_str) = &args.timeout {
        let timeout_dur = humantime::parse_duration(timeout_str)?;
        builder = builder.timeout(timeout_dur);
    }

    let connect_timeout_dur = humantime::parse_duration(&args.connect_timeout)?;
    builder = builder.connect_timeout(connect_timeout_dur);

    if let Some(proxy_url) = &args.proxy {
        let proxy = reqwest::Proxy::all(proxy_url)?;
        builder = builder.proxy(proxy);
    }

    Ok(builder.build()?)
}

fn build_body(args: &Args) -> Result<Option<String>> {
    if let Some(body_str) = &args.body_string {
        return Ok(Some(body_str.clone()));
    }

    if let Some(body_path) = &args.body_path {
        let content = std::fs::read_to_string(body_path)?;
        return Ok(Some(content));
    }

    if let Some(body_path_lines) = &args.body_path_lines {
        let content = std::fs::read_to_string(body_path_lines)?;
        // For now, just return the first line (actual implementation would handle line by line)
        return Ok(content.lines().next().map(|s| s.to_string()));
    }

    Ok(None)
}

fn parse_number(s: &str) -> Result<u64> {
    let s = s.trim().to_lowercase();
    if s.ends_with('k') {
        Ok(s.trim_end_matches('k').parse::<u64>()? * 1_000)
    } else if s.ends_with('m') {
        Ok(s.trim_end_matches('m').parse::<u64>()? * 1_000_000)
    } else {
        Ok(s.parse::<u64>()?)
    }
}

fn parse_duration(s: Option<&str>) -> Option<Duration> {
    s.and_then(|s| humantime::parse_duration(s).ok())
}

fn dialup_duration(duration: Duration) -> Duration {
    // This is a placeholder - actual implementation would measure actual dialup time
    duration
}
