use crate::cli::{Args, OutputFormat, TimeUnit};
use crate::stats::Statistics;
use anyhow::Result;
use std::fs::File;
use std::io::Write;
use std::time::Duration;
use serde_json::json;

pub fn write_results(args: &Args, stats: &Statistics) -> Result<()> {
    let output = match args.output_format {
        OutputFormat::Text => format_text(args, stats),
        OutputFormat::Json => format_json(stats)?,
        OutputFormat::Csv => format_csv(stats),
        OutputFormat::Quiet => String::new(),
    };

    if let Some(output_path) = &args.output {
        let mut file = File::create(output_path)?;
        file.write_all(output.as_bytes())?;
    } else {
        print!("{}", output);
    }

    Ok(())
}

fn format_text(args: &Args, stats: &Statistics) -> String {
    let mut output = String::new();

    let time_unit = args.time_unit.unwrap_or_else(|| {
        // Auto-determine time unit
        if let Some(avg) = stats.avg_duration() {
            if avg.as_millis() > 0 {
                TimeUnit::Milliseconds
            } else if avg.as_micros() > 0 {
                TimeUnit::Microseconds
            } else {
                TimeUnit::Nanoseconds
            }
        } else {
            TimeUnit::Milliseconds
        }
    });

    let factor = time_unit.factor() / 1_000_000_000.0; // Convert from nanos to the desired unit

    output.push_str("Summary:\n");
    output.push_str(&format!(
        "  Success rate:\t{:.2}%\n",
        stats.success_rate() * 100.0
    ));

    let total_duration = stats.total_duration();
    output.push_str(&format!(
        "  Total:\t{:.4} {}\n",
        total_duration.as_secs_f64() * factor,
        time_unit.as_str()
    ));

    if let Some(slowest) = stats.max_duration() {
        output.push_str(&format!(
            "  Slowest:\t{:.4} {}\n",
            slowest.as_secs_f64() * factor,
            time_unit.as_str()
        ));
    }

    if let Some(fastest) = stats.min_duration() {
        output.push_str(&format!(
            "  Fastest:\t{:.4} {}\n",
            fastest.as_secs_f64() * factor,
            time_unit.as_str()
        ));
    }

    if let Some(avg) = stats.avg_duration() {
        output.push_str(&format!(
            "  Average:\t{:.4} {}\n",
            avg.as_secs_f64() * factor,
            time_unit.as_str()
        ));
    }

    output.push_str(&format!(
        "  Requests/sec:\t{:.4}\n",
        stats.requests_per_sec()
    ));

    output.push_str("\n");
    output.push_str(&format!("  Total data:\t{}\n", format_bytes(stats.total_bytes())));
    output.push_str(&format!("  Size/request:\t{} B\n", stats.avg_size()));
    output.push_str(&format!(
        "  Size/sec:\t{}/s\n",
        format_bytes_rate(stats.size_per_sec())
    ));

    // Histogram
    output.push_str("\nResponse time histogram:\n");
    let histogram = stats.histogram_buckets(10);
    if !histogram.is_empty() {
        let max_count = histogram.values().max().copied().unwrap_or(1);
        for (bucket, count) in histogram {
            let duration = Duration::from_nanos(bucket);
            let bar_width = (*count as f64 / max_count as f64 * 40.0) as usize;
            output.push_str(&format!(
                "  {:.4} {} [{}] |{}\n",
                duration.as_secs_f64() * factor,
                time_unit.as_str(),
                count,
                "■".repeat(bar_width)
            ));
        }
    }

    // Percentiles
    output.push_str("\nResponse time distribution:\n");
    let percentiles = vec![10, 25, 50, 75, 90, 95, 99];
    for p in percentiles {
        if let Some(duration) = stats.get_percentile(p as f64) {
            output.push_str(&format!(
                "  {}%.00 in {:.4} {}\n",
                p,
                duration.as_secs_f64() * factor,
                time_unit.as_str()
            ));
        }
    }
    if let Some(duration) = stats.get_percentile(99.9) {
        output.push_str(&format!(
            "  99.90% in {:.4} {}\n",
            duration.as_secs_f64() * factor,
            time_unit.as_str()
        ));
    }
    if let Some(duration) = stats.get_percentile(99.99) {
        output.push_str(&format!(
            "  99.99% in {:.4} {}\n",
            duration.as_secs_f64() * factor,
            time_unit.as_str()
        ));
    }

    // Details
    output.push_str("\nDetails (average, fastest, slowest):\n");
    output.push_str("  DNS+dialup:\t");
    if let Some(avg) = stats.avg_duration() {
        let avg_dialup = avg / stats.results.len() as u32;
        output.push_str(&format!("{:.4} {}", avg_dialup.as_secs_f64() * factor, time_unit.as_str()));
        if let Some(min) = stats.min_duration() {
            output.push_str(&format!(", {:.4} {}", min.as_secs_f64() * factor, time_unit.as_str()));
        }
        if let Some(max) = stats.max_duration() {
            output.push_str(&format!(", {:.4} {}", max.as_secs_f64() * factor, time_unit.as_str()));
        }
    }
    output.push_str("\n");

    // For simplicity, we're not tracking DNS and dialup separately yet
    output.push_str("  DNS-lookup:\t0.0000 ");
    output.push_str(time_unit.as_str());
    output.push_str(", 0.0000 ");
    output.push_str(time_unit.as_str());
    output.push_str(", 0.0000 ");
    output.push_str(time_unit.as_str());
    output.push_str("\n");

    // Status code distribution
    output.push_str("\nStatus code distribution:\n");
    let status_dist = stats.status_code_distribution();
    for (status, count) in status_dist {
        output.push_str(&format!("  [{}] {} responses\n", status, count));
    }

    output
}

