    pub url: String,
    pub n_requests: u64,
    pub n_connections: usize,
    pub n_http2_parallel: usize,
    pub method: String,
    pub headers: Vec<String>,
    pub timeout: Option<String>,
    pub output: Option<PathBuf>,
    pub output_format: OutputFormat,
    pub debug: bool,
    pub version: bool,
    pub help: bool,
    pub no_tui: bool,
    pub connect_timeout: String,
    pub disable_keepalive: bool,
    pub insecure: bool,
    pub disable_compression: bool,
    pub redirect: usize,
    pub duration: Option<String>,
    pub query_per_second: Option<f64>,
    pub time_unit: Option<TimeUnit>,
    pub no_color: bool,
}

#[derive(Debug, Clone, Copy)]
pub enum OutputFormat {
    Text,
    Json,
    Csv,
    Quiet,
}

#[derive(Debug, Clone, Copy)]
pub enum TimeUnit {
    Nanoseconds,
    Microseconds,
    Milliseconds,
    Seconds,
    Minutes,
    Hours,
}

impl TimeUnit {
    pub fn as_str(&self) -> &str {
        match self {
            TimeUnit::Nanoseconds => "ns",
            TimeUnit::Microseconds => "us",
            TimeUnit::Milliseconds => "ms",
            TimeUnit::Seconds => "s",
            TimeUnit::Minutes => "m",
            TimeUnit::Hours => "h",
        }
    }

    pub fn factor(&self) -> f64 {
        match self {
            TimeUnit::Nanoseconds => 1.0,
            TimeUnit::Microseconds => 1_000.0,
            TimeUnit::Milliseconds => 1_000_000.0,
            TimeUnit::Seconds => 1_000_000_000.0,
            TimeUnit::Minutes => 60.0 * 1_000_000_000.0,
            TimeUnit::Hours => 3600.0 * 1_000_000_000.0,
        }
    }
}

pub fn parse_args(args: Vec<String>) -> Result<Args, String> {
    let mut result = Args {
        url: String::new(),
        n_requests: 200,
        n_connections: 50,
        n_http2_parallel: 1,
        method: "GET".to_string(),
        headers: Vec::new(),
        timeout: None,
        output: None,
        output_format: OutputFormat::Text,
        debug: false,
        version: false,
        help: false,
        no_tui: false,
        connect_timeout: "5s".to_string(),
        disable_keepalive: false,
        insecure: false,
        disable_compression: false,
        redirect: 10,
        duration: None,
        query_per_second: None,
        time_unit: None,
        no_color: false,
    };

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];

        if arg == "-h" || arg == "--help" {
            result.help = true;
            i += 1;
        } else if arg == "-V" || arg == "--version" {
            result.version = true;
            i += 1;
        } else if arg == "--debug" {
            result.debug = true;
            i += 1;
        } else if arg == "--no-tui" {
            result.no_tui = true;
            i += 1;
        } else if arg == "--disable-keepalive" {
            result.disable_keepalive = true;
            i += 1;
        } else if arg == "--insecure" {
            result.insecure = true;
            i += 1;
        } else if arg == "--disable-compression" {
            result.disable_compression = true;
            i += 1;
        } else if arg == "--no-color" || arg.starts_with("--no-color=") {
            result.no_color = true;
            i += 1;
        } else if arg == "-n" {
            i += 1;
            if i >= args.len() {
                return Err("Missing value for -n".to_string());
            }
            result.n_requests = parse_number(&args[i])?;
            i += 1;
        } else if arg == "-c" {
            i += 1;
            if i >= args.len() {
                return Err("Missing value for -c".to_string());
            }
            result.n_connections = args[i].parse()
                .map_err(|_| format!("Invalid number for -c: {}", args[i]))?;
            i += 1;
        } else if arg == "-p" {
            i += 1;
            if i >= args.len() {
                return Err("Missing value for -p".to_string());
            }
            result.n_http2_parallel = args[i].parse()
                .map_err(|_| format!("Invalid number for -p: {}", args[i]))?;
            i += 1;
        } else if arg == "-m" || arg == "--method" {
            i += 1;
            if i >= args.len() {
                return Err("Missing value for --method".to_string());
            }
            result.method = args[i].clone();
            i += 1;
        } else if arg == "-H" {
            i += 1;
            if i >= args.len() {
                return Err("Missing value for -H".to_string());
            }
            result.headers.push(args[i].clone());
            i += 1;
        } else if arg == "-t" {
            i += 1;
            if i >= args.len() {
                return Err("Missing value for -t".to_string());
            }
            result.timeout = Some(args[i].clone());
            i += 1;
        } else if arg == "-z" {
            i += 1;
            if i >= args.len() {
                return Err("Missing value for -z".to_string());
            }
            result.duration = Some(args[i].clone());
            i += 1;
        } else if arg == "-q" {
            i += 1;
            if i >= args.len() {
                return Err("Missing value for -q".to_string());
            }
            result.query_per_second = Some(args[i].parse()
                .map_err(|_| format!("Invalid float for -q: {}", args[i]))?);
            i += 1;
        } else if arg == "-o" || arg == "--output" {
            i += 1;
            if i >= args.len() {
                return Err("Missing value for -o".to_string());
            }
            result.output = Some(PathBuf::from(&args[i]));
            i += 1;
        } else if arg == "--output-format" {
            i += 1;
            if i >= args.len() {
                return Err("Missing value for --output-format".to_string());
            }
            result.output_format = match args[i].as_str() {
                "text" => OutputFormat::Text,
                "json" => OutputFormat::Json,
                "csv" => OutputFormat::Csv,
                "quiet" => OutputFormat::Quiet,
                _ => return Err(format!("Invalid output format: {}", args[i])),
            };
            i += 1;
        } else if arg == "-u" || arg == "--time-unit" {
            i += 1;
            if i >= args.len() {
                return Err("Missing value for --time-unit".to_string());
            }
            result.time_unit = Some(match args[i].as_str() {
                "ns" => TimeUnit::Nanoseconds,
                "us" => TimeUnit::Microseconds,
                "ms" => TimeUnit::Milliseconds,
                "s" => TimeUnit::Seconds,
                "m" => TimeUnit::Minutes,
                "h" => TimeUnit::Hours,
                _ => return Err(format!("Invalid time unit: {}", args[i])),
            });
            i += 1;
        } else if arg == "--connect-timeout" {
            i += 1;
            if i >= args.len() {
                return Err("Missing value for --connect-timeout".to_string());
            }
            result.connect_timeout = args[i].clone();
            i += 1;
        } else if arg == "-r" || arg == "--redirect" {
            i += 1;
            if i >= args.len() {
                return Err("Missing value for -r".to_string());
            }
            result.redirect = args[i].parse()
                .map_err(|_| format!("Invalid number for -r: {}", args[i]))?;
            i += 1;
        } else if arg.starts_with("-") {
            return Err(format!("Unknown option: {}", arg));
        } else {
            if result.url.is_empty() {
                result.url = arg.clone();
            }
            i += 1;
        }
    }

    if !result.help && !result.version && result.url.is_empty() {
        return Err("URL is required".to_string());
    }

    Ok(result)
}

pub fn parse_number(s: &str) -> Result<u64, String> {
    let s = s.trim().to_lowercase();
    if s.ends_with('k') {
        let num = s.trim_end_matches('k').parse::<u64>()
            .map_err(|_| format!("Invalid number: {}", s))?;
        Ok(num * 1_000)
    } else if s.ends_with('m') {
        let num = s.trim_end_matches('m').parse::<u64>()
            .map_err(|_| format!("Invalid number: {}", s))?;
        Ok(num * 1_000_000)
    } else {
        s.parse::<u64>()
            .map_err(|_| format!("Invalid number: {}", s))
    }
}
