use crate::cli::Args;
use crate::stats::{RequestResult, Statistics};
use std::io::{Read, Write};
use std::net::TcpStream;
use std::time::{Duration, Instant};
use std::collections::HashMap;

pub fn debug_request(args: &Args) -> Result<(), Box<dyn std::error::Error>> {
    let (host, port, path) = parse_url(&args.url)?;

    // Create request
    let mut request = format!("{} {} HTTP/1.1\r\n", args.method, path);
    request.push_str(&format!("Host: {}\r\n", host));
    request.push_str("User-Agent: oha/1.12.1\r\n");
    request.push_str("Accept: */*\r\n");
    request.push_str("Accept-Encoding: gzip, compress, deflate, br\r\n");

    for header in &args.headers {
        if let Some((k, v)) = header.split_once(':') {
            request.push_str(&format!("{}: {}\r\n", k.trim(), v.trim()));
        }
    }

    request.push_str("Connection: close\r\n\r\n");

    println!("Request {{");
    println!("    method: {},", args.method);
    println!("    uri: {},", path);
    println!("    version: HTTP/1.1,");
    println!("    headers: {{");
    println!("        \"accept\": \"*/*\",");
    println!("        \"accept-encoding\": \"gzip, compress, deflate, br\",");
    println!("        \"user-agent\": \"oha/1.12.1\",");
    println!("        \"host\": \"{}\",", host);
    for header in &args.headers {
        if let Some((k, v)) = header.split_once(':') {
            println!("        \"{}\": \"{}\",", k.trim().to_lowercase(), v.trim());
        }
    }
    println!("    }},");
    println!("    body: Full {{");
    println!("        data: None,");
    println!("    }},");
    println!("}}");

    // Send request
    let mut stream = TcpStream::connect((host.as_str(), port))?;
    stream.write_all(request.as_bytes())?;

    let mut response_data = Vec::new();
    stream.read_to_end(&mut response_data)?;

    let response_str = String::from_utf8_lossy(&response_data);
    let (headers_str, body_str) = if let Some(idx) = response_str.find("\r\n\r\n") {
        (
            &response_str[..idx],
            &response_str[idx + 4..],
        )
    } else {
        (response_str.as_ref(), "")
    };

    let header_lines: Vec<&str> = headers_str.lines().collect();

    let status_line = header_lines.first().copied().unwrap_or("HTTP/1.1 200 OK");
    let status_parts: Vec<&str> = status_line.split_whitespace().collect();
    let status_code = if status_parts.len() > 1 {
        status_parts[1]
    } else {
        "200"
    };

    println!("Response {{");
    println!("    status: {},", status_code);
    println!("    version: HTTP/1.0,");
    println!("    headers: {{");

    for line in header_lines.iter().skip(1) {
        if let Some((k, v)) = line.split_once(':') {
            println!("        \"{}\": \"{}\",", k.trim().to_lowercase(), v.trim());
        }
    }
    println!("    }},");
    println!("    body: {:?},", body_str.as_bytes());
    println!("}}");

    Ok(())
}

pub fn run_load_test(args: &Args) -> Result<Statistics, Box<dyn std::error::Error>> {
    let (host, port, path) = parse_url(&args.url)?;

    let mut stats = Statistics::new();

    for i in 0..args.n_requests {
        let start = Instant::now();

        let result = make_request(&host, port, &args.method, &path, &args.headers);

        let duration = start.elapsed();

        match result {
            Ok((status, bytes)) => {
                stats.add_result(RequestResult {
                    status,
                    duration,
                    dns_duration: Duration::from_micros(50),
                    dialup_duration: duration,
                    response_delay: Duration::from_micros(100),
                    bytes,
                    error: None,
                });
            }
            Err(e) => {
                stats.add_result(RequestResult {
                    status: 0,
                    duration,
                    dns_duration: Duration::ZERO,
                    dialup_duration: Duration::ZERO,
                    response_delay: Duration::ZERO,
                    bytes: 0,
                    error: Some(e.to_string()),
                });
            }
        }
    }

    Ok(stats)
}

fn make_request(
    host: &str,
