cat > /workspace/src/main.rs << 'MAINEOF'
use std::env;
use std::process;

mod cli;
mod http_client;
mod stats;
mod output;

use cli::parse_args;

fn main() {
    let args = match parse_args(env::args().collect()) {
        Ok(args) => args,
        Err(e) => {
            eprintln!("Error: {}", e);
            process::exit(1);
        }
    };

    if let Err(e) = run(&args) {
        eprintln!("Error: {}", e);
        process::exit(1);
    }
}

fn run(args: &cli::Args) -> Result<(), Box<dyn std::error::Error>> {
    if args.version {
        println!("oha 1.12.1");
        return Ok(());
    }

    if args.help {
        print_help();
        return Ok(());
    }

    if args.debug {
        http_client::debug_request(&args)?;
        return Ok(());
    }

    // Run the load test
    let stats = http_client::run_load_test(&args)?;

    // Output the results
    output::write_results(&args, &stats)?;

    Ok(())
}

fn print_help() {
    println!("Ohayou(おはよう), HTTP load generator, inspired by rakyll/hey with tui animation.");
    println!();
    println!("Usage: oha [OPTIONS] <URL>");
    println!();
    println!("Arguments:");
    println!("  <URL>  Target URL or file with multiple URLs.");
    println!();
    println!("Options:");
    println!("  -n <N_REQUESTS>");
