pub fn run_load_test(args: &Args) -> Result<Statistics, Box<dyn std::error::Error>> {
    let (host, port, path) = parse_url(&args.url)?;

    let mut stats = Statistics::new();

    let test_start = Instant::now();
    for _i in 0..args.n_requests {
        let start = Instant::now();

        let result = make_request(&host, port, &args.method, &path, &args.headers);

        let duration = start.elapsed();

        match result {
            Ok((status, bytes)) => {
                stats.add_result(RequestResult {
                    status,
                    duration,
                    dns_duration: Duration::from_micros(50),
                    dialup_duration: duration,
                    response_delay: Duration::from_micros(100),
                    bytes,
                    error: None,
                });
            }
            Err(e) => {
                stats.add_result(RequestResult {
                    status: 0,
                    duration,
                    dns_duration: Duration::ZERO,
                    dialup_duration: Duration::ZERO,
                    response_delay: Duration::ZERO,
                    bytes: 0,
                    error: Some(e.to_string()),
                });
            }
        }
    }

    // Update the end time to match when the test finished
    stats.end_time = test_start.elapsed() + stats.start_time;

    Ok(stats)
}

fn make_request(
    host: &str,
    port: u16,
    method: &str,
    path: &str,
    headers: &[String],
) -> Result<(u16, usize), Box<dyn std::error::Error>> {
    let mut request = format!("{} {} HTTP/1.1\r\n", method, path);
    request.push_str(&format!("Host: {}\r\n", host));
    request.push_str("User-Agent: oha/1.12.1\r\n");
    request.push_str("Accept: */*\r\n");
    request.push_str("Connection: close\r\n");

    for header in headers {
        if let Some((k, v)) = header.split_once(':') {
            request.push_str(&format!("{}: {}\r\n", k.trim(), v.trim()));
        }
    }

    request.push_str("\r\n");

    let mut stream = TcpStream::connect((host, port))?;
    stream.write_all(request.as_bytes())?;

    let mut response_data = Vec::new();
    stream.read_to_end(&mut response_data)?;

    let response_str = String::from_utf8_lossy(&response_data);
    let status_line = response_str.lines().next().unwrap_or("HTTP/1.1 200 OK");
    let status_parts: Vec<&str> = status_line.split_whitespace().collect();
    let status_code: u16 = if status_parts.len() > 1 {
        status_parts[1].parse().unwrap_or(200)
    } else {
        200
    };

    // Only count body bytes, not headers
    let body_bytes = if let Some(idx) = response_str.find("\r\n\r\n") {
        response_str[idx + 4..].as_bytes().len()
    } else {
        0
    };

    Ok((status_code, body_bytes))
}

pub fn parse_url(url: &str) -> Result<(String, u16, String), Box<dyn std::error::Error>> {
    let url = if url.starts_with("http://") {
        &url[7..]
    } else if url.starts_with("https://") {
        &url[8..]
    } else {
        url
    };

    let (host_port, path) = if let Some(idx) = url.find('/') {
        (url[..idx].to_string(), url[idx..].to_string())
    } else {
        (url.to_string(), "/".to_string())
    };

    let (host, port) = if let Some(idx) = host_port.find(':') {
        (
            host_port[..idx].to_string(),
            host_port[idx + 1..].parse().unwrap_or(80),
        )
    } else {
        (host_port, 80)
    };

    Ok((host, port, path))
}
