use std::time::{Duration, Instant};
use std::collections::BTreeMap;

#[derive(Clone)]
struct RequestResult {
    duration: Duration,
}

struct Statistics {
    results: Vec<RequestResult>,
    start_time: Instant,
    end_time: Instant,
}

impl Statistics {
    fn new() -> Self {
        let now = Instant::now();
        Statistics {
            results: Vec::new(),
            start_time: now,
            end_time: now,
        }
    }

    fn add_result(&mut self, result: RequestResult) {
        self.results.push(result);
        self.end_time = Instant::now();
    }

    fn total_duration(&self) -> Duration {
        self.end_time.duration_since(self.start_time)
    }
}

fn main() {
    let mut stats = Statistics::new();

    for _ in 0..3 {
        std::thread::sleep(Duration::from_millis(10));
        let duration = Duration::from_millis(10);
        stats.add_result(RequestResult { duration });
    }

    let total = stats.total_duration();
    println!("Total: {:?}", total);
    println!("Total nanos: {}", total.as_nanos());
    println!("Total micros: {}", total.as_micros());
    println!("Total millis: {}", total.as_millis());
    println!("Total secs_f64: {}", total.as_secs_f64());

    let avg = stats.results[0].duration;
    println!("Avg: {:?}", avg);
    println!("Avg.as_millis(): {}", avg.as_millis());
}
