            output.push_str(&format!(", {:.4} {}", max.as_secs_f64() * factor, time_unit.as_str()));
        }
    }
    output.push_str("\n");

    output.push_str("  DNS-lookup:\t0.0000 ");
    output.push_str(time_unit.as_str());
    output.push_str(", 0.0000 ");
    output.push_str(time_unit.as_str());
    output.push_str(", 0.0000 ");
    output.push_str(time_unit.as_str());
    output.push_str("\n");

    // Status code distribution
    output.push_str("\nStatus code distribution:\n");
    let status_dist = stats.status_code_distribution();
    for (status, count) in status_dist {
        output.push_str(&format!("  [{}] {} responses\n", status, count));
    }

    output
}

fn format_json(stats: &Statistics) -> String {
    let mut output = String::from("{\n");

    output.push_str("  \"summary\": {\n");
    output.push_str(&format!("    \"successRate\": {},\n", stats.success_rate()));
    output.push_str(&format!("    \"total\": {},\n", stats.total_duration().as_secs_f64()));
    if let Some(max) = stats.max_duration() {
        output.push_str(&format!("    \"slowest\": {},\n", max.as_secs_f64()));
    }
    if let Some(min) = stats.min_duration() {
        output.push_str(&format!("    \"fastest\": {},\n", min.as_secs_f64()));
    }
    if let Some(avg) = stats.avg_duration() {
        output.push_str(&format!("    \"average\": {},\n", avg.as_secs_f64()));
    }
    output.push_str(&format!("    \"requestsPerSec\": {},\n", stats.requests_per_sec()));
    output.push_str(&format!("    \"totalData\": {},\n", stats.total_bytes()));
    output.push_str(&format!("    \"sizePerRequest\": {},\n", stats.avg_size()));
    output.push_str(&format!("    \"sizePerSec\": {}\n", stats.size_per_sec()));
    output.push_str("  },\n");

    output.push_str("  \"responseTimeHistogram\": {\n");
    let histogram = stats.histogram_buckets(10);
    let mut first = true;
    for (bucket, count) in histogram {
        if !first {
            output.push_str(",\n");
        }
        let duration = std::time::Duration::from_nanos(bucket);
        output.push_str(&format!("    \"{}\": {}", duration.as_secs_f64(), count));
        first = false;
    }
    output.push_str("\n  },\n");

    output.push_str("  \"latencyPercentiles\": {\n");
    output.push_str(&format!("    \"p10\": {},\n", stats.get_percentile(10.0).map(|d| d.as_secs_f64()).unwrap_or(0.0)));
    output.push_str(&format!("    \"p25\": {},\n", stats.get_percentile(25.0).map(|d| d.as_secs_f64()).unwrap_or(0.0)));
    output.push_str(&format!("    \"p50\": {},\n", stats.get_percentile(50.0).map(|d| d.as_secs_f64()).unwrap_or(0.0)));
    output.push_str(&format!("    \"p75\": {},\n", stats.get_percentile(75.0).map(|d| d.as_secs_f64()).unwrap_or(0.0)));
    output.push_str(&format!("    \"p90\": {},\n", stats.get_percentile(90.0).map(|d| d.as_secs_f64()).unwrap_or(0.0)));
    output.push_str(&format!("    \"p95\": {},\n", stats.get_percentile(95.0).map(|d| d.as_secs_f64()).unwrap_or(0.0)));
    output.push_str(&format!("    \"p99\": {},\n", stats.get_percentile(99.0).map(|d| d.as_secs_f64()).unwrap_or(0.0)));
    output.push_str(&format!("    \"p99.9\": {},\n", stats.get_percentile(99.9).map(|d| d.as_secs_f64()).unwrap_or(0.0)));
    output.push_str(&format!("    \"p99.99\": {}\n", stats.get_percentile(99.99).map(|d| d.as_secs_f64()).unwrap_or(0.0)));
    output.push_str("  },\n");

    output.push_str("  \"rps\": {\n");
    output.push_str(&format!("    \"mean\": {},\n", stats.requests_per_sec()));
    output.push_str("    \"stddev\": null,\n");
    output.push_str(&format!("    \"max\": {},\n", stats.requests_per_sec()));
    output.push_str(&format!("    \"min\": {},\n", stats.requests_per_sec()));
    output.push_str("    \"percentiles\": {\n");
    output.push_str(&format!("      \"p10\": {},\n", stats.requests_per_sec()));
    output.push_str(&format!("      \"p25\": {},\n", stats.requests_per_sec()));
    output.push_str(&format!("      \"p50\": {},\n", stats.requests_per_sec()));
    output.push_str(&format!("      \"p75\": {},\n", stats.requests_per_sec()));
    output.push_str(&format!("      \"p90\": {},\n", stats.requests_per_sec()));
    output.push_str(&format!("      \"p95\": {},\n", stats.requests_per_sec()));
    output.push_str(&format!("      \"p99\": {},\n", stats.requests_per_sec()));
    output.push_str(&format!("      \"p99.9\": {},\n", stats.requests_per_sec()));
    output.push_str(&format!("      \"p99.99\": {}\n", stats.requests_per_sec()));
    output.push_str("    }\n");
    output.push_str("  },\n");

    output.push_str("  \"statusCodeDistribution\": {\n");
    let status_dist = stats.status_code_distribution();
    let mut first = true;
    for (status, count) in status_dist {
        if !first {
            output.push_str(",\n");
        }
        output.push_str(&format!("    \"{}\": {}", status, count));
        first = false;
    }
    output.push_str("\n  }\n");

    output.push_str("}\n");
    output
}

fn format_csv(stats: &Statistics) -> String {
    let mut output = String::new();
    output.push_str("request-start,DNS,DNS+dialup,Response-delay,request-duration,bytes,status\n");

    for (idx, result) in stats.results.iter().enumerate() {
        let elapsed = (idx as f64) * 0.001; // Rough estimate
        output.push_str(&format!(
            "{:.9},{:.9},{:.9},{:.9},{:.9},{},{}",
            elapsed,
            result.dns_duration.as_secs_f64(),
            result.dialup_duration.as_secs_f64(),
            result.response_delay.as_secs_f64(),
            result.duration.as_secs_f64(),
            result.bytes,
            result.status
        ));
        output.push('\n');
    }

    output
}

fn format_bytes(bytes: usize) -> String {
    const UNITS: &[&str] = &["B", "KiB", "MiB", "GiB"];
    let mut size = bytes as f64;
    let mut unit_idx = 0;

    while size >= 1024.0 && unit_idx < UNITS.len() - 1 {
        size /= 1024.0;
        unit_idx += 1;
    }

    format!("{:.2} {}", size, UNITS[unit_idx])
}

fn format_bytes_rate(bytes_per_sec: f64) -> String {
    const UNITS: &[&str] = &["B", "KiB", "MiB", "GiB"];
    let mut size = bytes_per_sec;
    let mut unit_idx = 0;

    while size >= 1024.0 && unit_idx < UNITS.len() - 1 {
        size /= 1024.0;
        unit_idx += 1;
    }

    format!("{:.2} {}", size, UNITS[unit_idx])
}
