}

impl TimeUnit {
    pub fn as_str(&self) -> &str {
        match self {
            TimeUnit::Nanoseconds => "ns",
            TimeUnit::Microseconds => "us",
            TimeUnit::Milliseconds => "ms",
            TimeUnit::Seconds => "s",
            TimeUnit::Minutes => "m",
            TimeUnit::Hours => "h",
        }
    }

    // Factor to multiply Duration.as_secs_f64() to get the desired unit
    pub fn factor(&self) -> f64 {
        match self {
            TimeUnit::Nanoseconds => 1_000_000_000.0,
            TimeUnit::Microseconds => 1_000_000.0,
            TimeUnit::Milliseconds => 1_000.0,
            TimeUnit::Seconds => 1.0,
            TimeUnit::Minutes => 1.0 / 60.0,
            TimeUnit::Hours => 1.0 / 3600.0,
        }
    }
}

pub fn parse_args(args: Vec<String>) -> Result<Args, String> {
    let mut result = Args {
